import { esc, image, link, paragraphs, enquiryForm } from './ui.mjs';

const text = (value) => esc(String(value ?? ''));
const split = (value) => String(value ?? '').split(/\n\s*\n/).map((part) => part.trim()).filter(Boolean);
const excerpt = (value, length = 180) => {
  const plain = String(value ?? '').replace(/\s+/g, ' ').trim();
  return plain.length > length ? `${plain.slice(0, length).replace(/\s+\S*$/, '')}…` : plain;
};
const slug = (value) => String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const list = (items) => `<ul class="detail-list">${items.map((item) => `<li>${text(item)}</li>`).join('')}</ul>`;
const phoneLink = (phone) => link(`tel:${String(phone).replace(/[^+\d]/g, '')}`, phone);
const emailLink = (email) => link(`mailto:${email}`, email);
const sourceLink = (url, label = 'Read the published source') => /^https?:\/\//.test(String(url ?? '')) ? link(url, label) : '';
const heading = (eyebrow, title, intro = '') => `<div class="page-section-head"><p class="eyebrow">${text(eyebrow)}</p><h2 class="display">${text(title)}</h2>${intro ? `<p class="lede">${text(intro)}</p>` : ''}</div>`;
const section = (body, attributes = '') => `<section class="section wrap"${attributes ? ` ${attributes}` : ''}>${body}</section>`;
const facts = (entries) => `<dl class="fact-row">${entries.map(([label, value]) => `<div><dt>${text(label)}</dt><dd>${text(value)}</dd></div>`).join('')}</dl>`;
const empty = '<p data-empty hidden role="status">No matches just yet. Try another search or choose a different category.</p>';
const search = (id, label, placeholder) => `<div class="search-field"><label for="${text(id)}">${text(label)}</label><input id="${text(id)}" type="search" data-search placeholder="${text(placeholder)}" autocomplete="off"></div>`;
const filters = (categories) => `<div class="filter-bar" aria-label="Filter by category"><button type="button" data-filter="all" aria-pressed="true">All</button>${categories.map((category) => `<button type="button" data-filter="${text(category)}" aria-pressed="false">${text(category)}</button>`).join('')}</div>`;
const itemAttributes = (category = '') => `data-search-item${category ? ` data-filter-item data-category="${text(category)}"` : ''}`;
const card = ({ href, title, eyebrow, key, copy = '', extra = '', label = 'Discover more', attributes = '', alt = '' }) => `<article class="image-card" ${attributes}><a class="card-media" href="${text(href)}" aria-label="${text(title)}">${image(key, alt || title)}</a><div class="card-copy"><p class="eyebrow">${text(eyebrow)}</p><h3>${link(href, title, '')}</h3>${copy ? `<p>${text(copy)}</p>` : ''}${extra}${link(href, label)}</div></article>`;
const roomImages = ['stay-bedroom-1', 'stay-bedroom-2', 'stay-balcony', 'stay-seating', 'stay-bedroom-2', 'stay-villa-balcony', 'stay-balcony', 'stay-villa-balcony'];
const diningImages = { dhani: 'dine-hall', somapuraa: 'dine-cocktails', 'sagar-bar': 'dine-poolside', 'panch-mahal': 'panch-wide' };
const roomCategory = (room) => /villa/i.test(room.name) ? 'Villas' : /suite/i.test(room.name) ? 'Suites' : 'Rooms';
const offerCategory = (offer) => /empress|affair|for-two/.test(offer.slug) ? 'For two' : /family|families/i.test(offer.description) ? 'Family escapes' : /day-use/.test(offer.slug) ? 'Daycation' : 'Plan & save';
const offerImage = (offer) => ({ 'For two': 'dine-romantic', 'Family escapes': 'estate-pool-day', Daycation: 'estate-wide', 'Plan & save': 'stay-bedroom-2' })[offerCategory(offer)];
const articleCategory = (article) => {
  const title = article.title.toLowerCase();
  if (/wedding|banquet|proposal|dealers|event/.test(title)) return 'Celebrations';
  if (/dining|culinary|gourmet|cake/.test(title)) return 'Dining';
  if (/spa|yoga|wellness/.test(title)) return 'Wellbeing';
  if (/temple|seashell|shores|charms|rajasthani|ritual/.test(title)) return 'Culture & coast';
  return 'Palace life';
};
const articleImage = (article) => ({ Celebrations: 'celeb-mandap', Dining: 'dine-table', Wellbeing: 'exp-yoga', 'Culture & coast': 'story-pavilion', 'Palace life': 'estate-wide' })[articleCategory(article)];
const experienceCategory = (name) => {
  if (/welcome|puppet|folk/i.test(name)) return 'Culture & connection';
  if (/dining/i.test(name)) return 'At the table';
  if (/yoga|spa|salon|fitness|^pool$/i.test(name)) return 'Rest & wellbeing';
  if (/parking|gift/i.test(name)) return 'Palace conveniences';
  return 'Play & discover';
};
